+      const time = item?.date || item?.recordTime || item?.sendTime || item?.warnTime
+      const date = time ? new Date(time) : null
+      const hour = date && !Number.isNaN(date.getTime()) ? date.getHours() : index % 24
+      hourlyData[hour] = number
+    })
+    return [{
+      name: '拉线位移(毫米)',
+      type: 'line',
+      smooth: false,
+      connectNulls: true,
